    address character varying(255),
    corpus character varying(255),
    phase character varying(255),
    deadline character varying(50),
    deadline_year integer,
    floors integer,
    lift boolean,
    parking boolean,
    latitude double precision,
    longitude double precision,
    building_status_id bigint,
    house_id bigint NOT NULL,
    house_structure_type_id bigint
);


ALTER TABLE public.houses_houseparams OWNER TO bh_database_connect;

